package com.music.bitchord.playback.audio

/**
 * The last step for every block the sink writes, decoded or generated by a
 * loop mix: the DSP chain, or under bit-perfect no processing at all and only
 * the listener's volume, applied here when the system mixer is out of the
 * path ([userGain] below 1).
 *
 * One function for both, so a loop mix's generated blocks can't run the
 * chain, or skip the volume, where a decoded block would not.
 */
internal object BlockFinish {
    fun apply(block: AudioBlock, skipDsp: Boolean, userGain: Float, process: (AudioBlock) -> Unit) {
        if (!skipDsp) {
            process(block)
        } else if (userGain < 0.999f) {
            val samples = block.samples
            for (index in 0 until block.sampleCount) samples[index] *= userGain
        }
    }
}
